mapper.select:
select distinct c.id, c.coach_name as coachName, c.avatar_url as avatarUrl, c.coach_level as coachLevel, c.intro, c.sort_no as sortNo from pt_coach c inner join pt_coach_store_rel csr on csr.coach_id = c.id inner join pt_coach_schedule sch on sch.coach_id = c.id and sch.store_id = csr.store_id and sch.is_enabled = 1 where c.status = 1 and c.deleted = 0 and csr.store_id in (select store_id from pt_product_store_rel where product_id = #{productId})
and csr.store_id = #{storeId}
and ( not exists (select 1 from pt_product_coach_rel where product_id = #{productId}) or c.id in (select coach_id from pt_product_coach_rel where product_id = #{productId}) ) order by c.sort_no desc, c.id asc

SELECT u.userId AS memberId, u.nickname AS memberName, u.phone AS memberMobile, u.headImgUrl AS headImgUrl, COUNT(b.id) AS benefitCount, SUM(CASE WHEN b.status = 1 AND (b.expire_at IS NULL OR b.expire_at > NOW()) THEN 1 ELSE 0 END) AS activeBenefitCount, IFNULL(SUM(CASE WHEN b.status = 1 AND (b.expire_at IS NULL OR b.expire_at > NOW()) THEN b.remaining_lessons ELSE 0 END), 0) AS remainingLessons, IFNULL(SUM(CASE WHEN b.status = 1 AND (b.expire_at IS NULL OR b.expire_at > NOW()) THEN b.frozen_lessons ELSE 0 END), 0) AS frozenLessons, GROUP_CONCAT(DISTINCT CASE WHEN b.status = 1 AND (b.expire_at IS NULL OR b.expire_at > NOW()) THEN p.product_name END ORDER BY p.product_name SEPARATOR '、') AS activeProductNames, GROUP_CONCAT(DISTINCT CASE WHEN b.status = 1 AND (b.expire_at IS NULL OR b.expire_at > NOW()) THEN s.storeName END ORDER BY s.storeName SEPARATOR '、') AS activeStoreNames, MAX(COALESCE(b.updated_at, b.created_at)) AS lastBenefitAt FROM pt_member_private_benefit b INNER JOIN user_info u ON u.userId = b.member_id AND u.isDel = 0 LEFT JOIN pt_product p ON p.id = b.product_id LEFT JOIN store_address sa ON sa.storeAddrId = b.store_id LEFT JOIN store s ON s.storeId = sa.storeId WHERE b.coach_id = #{coachId}
AND (u.nickname LIKE concat('%', #{keyword}, '%') OR u.phone LIKE concat('%', #{keyword}, '%') OR CAST(u.userId AS CHAR) LIKE concat('%', #{keyword}, '%'))
GROUP BY u.userId, u.nickname, u.phone, u.headImgUrl ORDER BY activeBenefitCount DESC, lastBenefitAt DESC, memberId DESC LIMIT #{offset}, #{limit}

SELECT b.id AS benefitId, b.benefit_no AS benefitNo, b.member_id AS memberId, b.product_id AS productId, COALESCE(p.product_name, o.product_name) AS productName, b.store_id AS storeId, COALESCE(s.storeName, sa.storeName) AS storeName, b.total_lessons AS totalLessons, b.used_lessons AS usedLessons, b.frozen_lessons AS frozenLessons, b.remaining_lessons AS remainingLessons, b.status, DATE_FORMAT(b.effective_at, '%Y-%m-%d %H:%i:%s') AS effectiveAt, DATE_FORMAT(b.expire_at, '%Y-%m-%d %H:%i:%s') AS expireAt FROM pt_member_private_benefit b LEFT JOIN pt_private_order o ON o.id = b.order_id LEFT JOIN pt_product p ON p.id = b.product_id LEFT JOIN store_address sa ON sa.storeAddrId = b.store_id LEFT JOIN store s ON s.storeId = sa.storeId WHERE b.coach_id = #{coachId} AND b.member_id IN
#{memberId}
ORDER BY b.member_id ASC, (b.status = 1 AND (b.expire_at IS NULL OR b.expire_at > NOW())) DESC, b.id DESC

SELECT
    ROUND(IFNULL(SUM(CASE WHEN status = 1 AND tradeType = 1 THEN money
                          WHEN status = 1 AND tradeType = 2 THEN -money ELSE 0 END), 0), 2) AS totalIncome,
    ROUND(IFNULL(SUM(CASE WHEN status = 1
                              AND COALESCE(transactionTime, createTime) >= #{monthStart}
                              AND COALESCE(transactionTime, createTime) < #{nextMonthStart}
                          THEN CASE WHEN tradeType = 2 THEN -money ELSE money END ELSE 0 END), 0), 2) AS monthIncome,
    ROUND(IFNULL(SUM(CASE WHEN status = 1 AND transactionNumber REGEXP '^PT_(LESSON|MONTHLY)_'
                              AND COALESCE(transactionTime, createTime) >= #{monthStart}
                              AND COALESCE(transactionTime, createTime) < #{nextMonthStart}
                          THEN CASE WHEN tradeType = 2 THEN -money ELSE money END ELSE 0 END), 0), 2) AS monthLessonIncome,
    ROUND(IFNULL(SUM(CASE WHEN status = 1 AND transactionNumber REGEXP '^PT_SALE_'
                              AND COALESCE(transactionTime, createTime) >= #{monthStart}
                              AND COALESCE(transactionTime, createTime) < #{nextMonthStart}
                          THEN CASE WHEN tradeType = 2 THEN -money ELSE money END ELSE 0 END), 0), 2) AS monthSaleIncome
FROM coach_trade_detail
WHERE coachId = #{coachId}
  AND transactionNumber REGEXP '^PT_(LESSON|MONTHLY|SALE)_'

SELECT COUNT(1)
FROM coach_trade_detail
WHERE coachId = #{coachId}
  AND transactionNumber REGEXP '^PT_(LESSON|MONTHLY|SALE)_'
  AND COALESCE(transactionTime, createTime) >= #{monthStart}
  AND COALESCE(transactionTime, createTime) < #{nextMonthStart}
AND transactionNumber REGEXP '^PT_(LESSON|MONTHLY)_'
AND transactionNumber REGEXP '^PT_SALE_'
